{
  "name": "dxkj",
  "version": "0.1.5",
  "description": "dxkj CLI — browse and install prompts/skills/agents/plugins/tools from the dxkj catalog, plus an opencode plugin shell.",
  "type": "module",
  "license": "Apache-2.0",
  "bin": {
    "dxkj": "bin/dxk.js"
  },
  "main": "./src/opencode.js",
  "exports": {
    ".": "./src/opencode.js",
    "./cli": "./src/cli.js",
    "./package.json": "./package.json"
  },
  "files": [
    "bin",
    "src",
    "fixtures",
    "README.md"
  ],
  "engines": {
    "node": ">=18.17"
  },
  "dependencies": {
    "adm-zip": "^0.5.16"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public"
  },
  "keywords": [
    "dxkj",
    "cli",
    "opencode",
    "skill",
    "agent",
    "prompt",
    "catalog"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://gitee.com/amdyhaha/navlink_release_amdy.git"
  }
}
